import re

from copy import deepcopy


def get_ue_config(source_ue, uecap_config, uecap_ini):
    ues = {}
    for ue in source_ue['ue']:
        ue_config = deepcopy(ue)
        ue_config['imeisv'] = ue.get('imeisv', '3207212145000001')

        ueid_match = re.match(r' ?(.*): ?(.*) ?', ue.get('ueid', ''))
        if ueid_match:
            ueid_start = ueid_match.group(1)
            ueid_stop = ueid_match.group(2)
            list_ues = list(range(int(ueid_start), int(ueid_stop)))
        else:
            list_ues = [ue['ueid']]

        if 'cat' not in ue_config:
            ue_config['cat'] = uecap_ini.get(ue['profile'], {}).get('ue-Category', '3')

        ue_config['ue_caps_cdma'] = uecap_config.get('cdma2k1xRtt_capabilities', '')
        ue_config['ue_caps_utra'] = uecap_config.get('utra_capabilities', '')
        ue_config['ue_caps_geran'] = uecap_config.get('geran_cs_capabilities', '')
        ue_config['ue_caps_index'] = uecap_ini[ue['profile']]['INDEX']
        ue_config['ue_caps_asn'] = uecap_config[ue['profile']]

        for ueid in list_ues:
            h_ue = deepcopy(ue_config)
            h_ue['ueid'] = ueid
            h_ue['imsi'] = ue_config['mcc'] + ue_config['mnc'] + h_ue['msin']
            h_ue['pmi'] = ue_config.get('pmi', '1') if 'pmi' in ue else '1'
            h_ue['ri'] = ue.get('ri', '2')
            h_ue['cqi'] = ue.get('cqi', '15')
            h_ue['autn'] = ue_config.get('autn', source_ue['UE_AUTN'])
            h_ue['rand'] = ue_config.get('autn', source_ue['UE_RAND'])
            h_ue['eea'] = ue_config.get('eea', 'NULL')
            h_ue['eia'] = ue_config.get('eia', 'NULL')
            ues[ueid] = h_ue
    source_ue['ue'] = ues
    return source_ue
